import { promises as fs } from "node:fs/promises";
import * as path from "node:path";
import type { BranchState } from "../mech/types";

const STATE_PATH = ".morphmap/state.json";

export async function loadState(statePath: string = STATE_PATH): Promise<BranchState | null> {
  try {
    const content = await fs.readFile(statePath, "utf8");
    return JSON.parse(content) as BranchState;
  } catch (e: any) {
    if (e.code === "ENOENT") return null;
    throw new Error(`Failed to load state from ${statePath}: ${e.message}`);
  }
}

export async function saveState(state: BranchState, statePath: string = STATE_PATH): Promise<void> {
  const dir = path.dirname(statePath);
  await fs.mkdir(dir, { recursive: true });

  const tmpPath = `${statePath}.tmp`;
  const content = JSON.stringify(state, null, 2);
  await fs.writeFile(tmpPath, content, "utf8");

  // fsync for crash safety
  const fd = await fs.open(tmpPath, "r+");
  try {
    await fd.sync();
  } finally {
    await fd.close();
  }

  // atomic rename
  await fs.rename(tmpPath, statePath);
}
```

