    return {
      ok: true,
      summary: `leaf '${leafId}' submitted`,
      failures: [],
      newState: result.newState,
    };
  }

  return {
    ok: false,
    summary: `submission rejected: ${result.failures.join(", ")}`,
    failures: result.failures,
    newState: state,
  };
}

