/**
 * mech — seed.ts
 * Pure parser: mindmap markdown → structured branch/leaf data.
 * Zero pi imports, zero I/O. Used by morphmap-seed.ts (impure) and
 * md↔json sync hook.
 *
 * Spec: docs/mech-mindmap.md §2.7 Step A, §6.1
 */
import type {
  BranchStatus,
  Bottleneck,
  LeafStatus,
  QALevel,
  TestStrategy,
} from "./types";

// ── Emoji → status mappings ──────────────────────────────────
// Single source of truth for mindmap rendering.
export const LEAF_EMOJI_MAP: Record<string, LeafStatus> = {
  "⬜": "pending",
  "🔄": "in_progress",
  "⏳": "submitted",
  "🔴": "blocked",
  "💤": "abandoned",
  "✅": "done",
};

export const BRANCH_EMOJI_MAP: Record<string, BranchStatus> = {
  "⬜": "pending",
  "🔄": "in_progress",
  "✅": "done",
  "🔴": "blocked",
  "💤": "abandoned",
};

// ── Parsed data structures ───────────────────────────────────
export interface ParsedLeaf {
  id: string;
  name: string;
  status: LeafStatus;
  bottleneck: Bottleneck;
  qa: QALevel;
  test: TestStrategy[];
  specPath?: string;
  needs: string[];
  needsContract: string[];
  estLoc?: number;
  human: boolean;
}

export interface ParsedBranch {
  id: string;
  name: string;
  level: number; // 2 (##), 3 (###), 4 (####)
  status: BranchStatus;
  tags: string[];
  scope?: string;
  quality?: "fast" | "strict" | "none";
  leaves: ParsedLeaf[];
  subBranchIds: string[];
  childBranchStatus: Record<string, BranchStatus>;
}

// ── Helpers ──────────────────────────────────────────────────
function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function extractEmoji(text: string): { emoji: string; rest: string } | null {
  const match = text.match(/^(\p{Emoji_Presentation}|\p{Emoji})\s+(.*)$/u);
  if (!match) return null;
  return { emoji: match[1], rest: match[2] };
}

// ── Leaf line parser ─────────────────────────────────────────
export function parseLeafLine(line: string): ParsedLeaf | null {
  // Match: - emoji name → path [tags...]
  // or:    - emoji name (no path)
  const trimmed = line.trim();
  if (!trimmed.startsWith("- ")) return null;

  const content = trimmed.slice(2);
  const emojiMatch = extractEmoji(content);
  if (!emojiMatch) return null;

  const status = LEAF_EMOJI_MAP[emojiMatch.emoji];
  if (!status) return null;

  const rest = emojiMatch.rest;

  // Split on → to separate name from path
  const arrowIdx = rest.indexOf(" → ");
  let name: string;
  let specPath: string | undefined;

  if (arrowIdx >= 0) {
    name = rest.slice(0, arrowIdx).trim();
    // Path is everything after → up to the first [ or ·
    const afterArrow = rest.slice(arrowIdx + 3).trim();
    const pathEnd = Math.min(
      afterArrow.search(/[\[·]/) >= 0 ? afterArrow.search(/[\[·]/) : afterArrow.length,
      afterArrow.length,
    );
    specPath = afterArrow.slice(0, pathEnd).trim() || undefined;
  } else {
    // No arrow — just name and tags
    const tagStart = rest.search(/\[/);
    if (tagStart >= 0) {
      name = rest.slice(0, tagStart).trim();
    } else {
      name = rest.trim();
    }
  }

  // Extract tags
  const tagRegex = /\[([^\]]+)\]/g;
  const tags: string[] = [];
  let tagMatch;
  while ((tagMatch = tagRegex.exec(rest)) !== null) {
    tags.push(tagMatch[1]);
  }

  // Parse tags
  let qa: QALevel = "review";
  let bottleneck: Bottleneck = "standard";
  let test: TestStrategy[] = ["unit"];
  let needs: string[] = [];
  let needsContract: string[] = [];
  let estLoc: number | undefined;
  let human = false;

  for (const tag of tags) {
    if (tag.startsWith("qa:")) {
      qa = tag.slice(3).trim() as QALevel;
    } else if (tag.startsWith("test:")) {
      test = tag.slice(5).trim().split(/\s*\+\s*/).map(t => t.trim()) as TestStrategy[];
    } else if (tag.startsWith("bottleneck:")) {
      bottleneck = tag.slice(11).trim() as Bottleneck;
    } else if (tag.startsWith("needs:")) {
      needs.push(tag.slice(6).trim());
    } else if (tag.startsWith("needs-contract:")) {
      needsContract.push(tag.slice(15).trim());
    } else if (tag.startsWith("est-loc:")) {
      estLoc = parseInt(tag.slice(8).trim(), 10);
    } else if (tag === "human") {
      human = true;
    }
  }

  // Infer bottleneck from qa if not specified
  if (!tags.some(t => t.startsWith("bottleneck:"))) {
    if (qa === "full" || qa === "strict") bottleneck = "risky";
  }

  return {
    id: slugify(name),
    name,
    status,
    bottleneck,
    qa,
    test,
    specPath,
    needs,
    needsContract,
    estLoc,
    human,
  };
}

// ── Branch heading parser ────────────────────────────────────
export function parseBranchLine(line: string): ParsedBranch | null {
  // Match: ## name emoji [tag] — scope: desc · progress
  // or:    ## name emoji [tag]
  const match = line.match(/^(#{2,4})\s+(.+)$/);
  if (!match) return null;

  const level = match[1].length;
  const rest = match[2];

  // Extract emoji
  const emojiMatch = extractEmoji(rest);
  if (!emojiMatch) return null;

  const branchStatus = BRANCH_EMOJI_MAP[emojiMatch.emoji];
  if (!branchStatus) return null;

  // Extract name (before tags)
  const tagStart = emojiMatch.rest.search(/\[/);
  let name: string;
  let tagsStr: string;

  if (tagStart >= 0) {
    name = emojiMatch.rest.slice(0, tagStart).trim();
    tagsStr = emojiMatch.rest.slice(tagStart);
  } else {
    name = emojiMatch.rest.trim();
    tagsStr = "";
  }

  // Extract tags
  const tags: string[] = [];
  const tagRegex = /\[([^\]]+)\]/g;
  let tagMatch;
  while ((tagMatch = tagRegex.exec(tagsStr)) !== null) {
    tags.push(tagMatch[1]);
  }

  // Extract scope
  let scope: string | undefined;
  const scopeMatch = name.match(/—\s*scope:\s*(.+?)(?:\s*·|$)/);
  if (scopeMatch) {
    scope = scopeMatch[1].trim();
    name = name.replace(/—\s*scope:\s*.+?(?:\s*·|$)/, "").trim();
  }

  // Extract quality from tags
  let quality: "fast" | "strict" | "none" | undefined;
  for (const tag of tags) {
    if (tag.startsWith("quality:")) {
      quality = tag.slice(8).trim() as "fast" | "strict" | "none";
    }
  }

  return {
    id: slugify(name),
    name,
    level,
    status: branchStatus,
    tags,
    scope,
    quality,
    leaves: [],
    subBranchIds: [],
    childBranchStatus: {},
  };
}

// ── Full mindmap parser ──────────────────────────────────────
export function parseMapToBranches(content: string): ParsedBranch[] {
  const lines = content.split("\n");
  const branches: ParsedBranch[] = [];
  let currentBranch: ParsedBranch | null = null;
  let inFrontmatter = false;

  for (const line of lines) {
    // Skip frontmatter
    if (line.trim() === "---") {
      inFrontmatter = !inFrontmatter;
      continue;
    }
    if (inFrontmatter) continue;

    // Skip title
    if (line.startsWith("# ")) continue;

    // Skip empty lines
    if (line.trim() === "") continue;

    // Check for branch heading
    const branch = parseBranchLine(line);
    if (branch) {
      // Close previous branch if this is a new top-level or same-level branch
      if (currentBranch && branch.level <= currentBranch.level) {
        branches.push(currentBranch);
        currentBranch = null;
      }

      // If this is a sub-branch of the current branch, add as child
      if (currentBranch && branch.level > currentBranch.level) {
        currentBranch.subBranchIds.push(branch.id);
        currentBranch.childBranchStatus[branch.id] = branch.status;
        // Sub-branches are also added to the flat list
        branches.push(branch);
        currentBranch = branch;
      } else {
        if (currentBranch) {
          branches.push(currentBranch);
        }
        currentBranch = branch;
      }
      continue;
    }

    // Check for leaf line
    if (currentBranch && line.trim().startsWith("- ")) {
      const leaf = parseLeafLine(line);
      if (leaf) {
        currentBranch.leaves.push(leaf);
      }
    }
  }

  // Don't forget the last branch
  if (currentBranch) {
    branches.push(currentBranch);
  }

  return branches;
}
```

