Let me also think about the `branchToState` function. This converts a `ParsedBranch` to a `BranchState`:

```typescript
function branchToState(branch: ParsedBranch): BranchState {
  const leaves: Record<string, Leaf> = {};
  const nodes: string[] = [];
  const edges: DepEdge[] = [];

  for (const parsedLeaf of branch.leaves) {
    const model = assignModel(parsedLeaf.bottleneck, parsedLeaf.qa, parsedLeaf.test);
    const tools = assignTools(parsedLeaf.test, ["web"]); // default domain

    const leaf: Leaf = {
      id: parsedLeaf.id,
      status: parsedLeaf.status,
      bottleneck: parsedLeaf.bottleneck,
      qa: parsedLeaf.qa,
      test: parsedLeaf.test,
      model,
      tools,
      evidence: emptyEvidence(),
      reviewRounds: 0,
      trace: `${branch.id}/${parsedLeaf.id}`,
      estLoc: parsedLeaf.estLoc,
    };

    leaves[parsedLeaf.id] = leaf;
    nodes.push(parsedLeaf.id);

    // Create dependency edges
    for (const target of parsedLeaf.needs) {
      edges.push({ from: parsedLeaf.id, to: target, kind: "needs" });
    }
    for (const target of parsedLeaf.needsContract) {
      edges.push({ from: parsedLeaf.id, to: target, kind: "needs-contract" });
    }
  }

  return {
    branchId: branch.id,
    status: branch.status,
    quality: branch.quality ?? "fast",
    leaves,
    subBranches: branch.subBranchIds,
    childBranchStatus: branch.childBranchStatus,
    transitions: [],
    integrationStatus: {
      reviewFileExists: false,
      healthCheckPassed: null,
      bombadilPassed: null,
      lonkeroPassed: null,
      allLeavesComplete: false,
      crossLeafConflicts: [],
    },
  };
}
```

