```typescript
export async function seedFromMap(
  mindmapPath: string = ".morphmap/morphmap.mindmap.md",
  stateDir: string = ".morphmap",
): Promise<{ seeded: number; stateIndex: Record<string, string> }> {
  const content = await fs.readFile(mindmapPath, "utf8");
  const branches = parseMapToBranches(content);

  const stateIndex: Record<string, string> = {};
  let seeded = 0;

  for (const branch of branches) {
    if (branch.tags.includes("module") || branch.tags.includes("feature")) {
      const state = branchToState(branch);
      const statePath = path.join(stateDir, "plans", branch.id, "state.json");
      await fs.mkdir(path.dirname(statePath), { recursive: true });
      await saveState(state, statePath);
      stateIndex[branch.id] = statePath;
      seeded++;
    }
  }

  // Write root state
  const rootState = createRootState(branches);
  await saveState(rootState, path.join(stateDir, "state.json"));

  // Write state index
  await fs.writeFile(
    path.join(stateDir, "state-index.json"),
    JSON.stringify(stateIndex, null, 2),
    "utf8",
  );

  return { seeded, stateIndex };
}
```

